import{_ as r,o as e,c as a,a5 as n}from"./chunks/framework.R-FQ1xZ2.js";const c=JSON.parse('{"title":"面试准备总览","description":"","frontmatter":{"title":"面试准备总览","order":0},"headers":[],"relativePath":"interview/index.md","filePath":"interview/index.md","lastUpdated":null}'),s={name:"interview/index.md"};function o(d,t,l,i,g,h){return e(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="面试准备总览" tabindex="-1">面试准备总览 <a class="header-anchor" href="#面试准备总览" aria-label="Permalink to &quot;面试准备总览&quot;">​</a></h1><blockquote><p>这一节不是「知识」，是<strong>武器</strong>。八页里越靠前的，越能在 48 小时内见效。</p></blockquote><h2 id="如果你明天就有面试" tabindex="-1">如果你明天就有面试 <a class="header-anchor" href="#如果你明天就有面试" aria-label="Permalink to &quot;如果你明天就有面试&quot;">​</a></h2><p>按这个顺序读，别从头翻知识体系：</p><table tabindex="0"><thead><tr><th>顺序</th><th>读什么</th><th>花多久</th><th>读到什么程度</th></tr></thead><tbody><tr><td>1</td><td><a href="/learn/interview/project-grilling.html">项目深挖预演</a></td><td>40 min</td><td>两个项目的「口径卡」能背下来，数字的<strong>口径</strong>说得清</td></tr><tr><td>2</td><td><a href="/learn/interview/rag.html">RAG 高频题</a></td><td>30 min</td><td>能画端到端图 + 说清它为什么会失败</td></tr><tr><td>3</td><td><a href="/learn/interview/agent.html">Agent 与工具调用高频题</a></td><td>30 min</td><td>ReAct 循环能默写，工具调用生命周期能讲</td></tr><tr><td>4</td><td><a href="/learn/interview/llm.html">大模型原理高频题</a></td><td>20 min</td><td>注意力、KV Cache、位置编码三件套</td></tr><tr><td>5</td><td>对应项目的拆解页</td><td>60 min</td><td>讲到第三层追问不卡</td></tr></tbody></table><p><strong>不要</strong>在面试前夜去啃没读过的知识点。面试考的是你能不能把会的东西讲清楚，不是你会多少。</p><h2 id="面试官到底在问什么" tabindex="-1">面试官到底在问什么 <a class="header-anchor" href="#面试官到底在问什么" aria-label="Permalink to &quot;面试官到底在问什么&quot;">​</a></h2><p>同一个问题，面试官脑子里在同时跑五层判断。<strong>大部分人只回答了第一层。</strong></p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Q[&quot;面试官的问题&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Q --&gt; L1[&quot;第 1 层：他做过吗&lt;br/&gt;细节是否具体到能复述&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  L1 --&gt; L2[&quot;第 2 层：他知道为什么吗&lt;br/&gt;选型有依据还是照抄教程&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  L2 --&gt; L3[&quot;第 3 层：他遇到问题怎么排查&lt;br/&gt;有方法论还是靠试&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  L3 --&gt; L4[&quot;第 4 层：他说的话可信吗&lt;br/&gt;数字有没有口径、边界是否自知&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  L4 --&gt; L5[&quot;第 5 层：能迁移吗&lt;br/&gt;换个场景还成立吗&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>对应到你的答案，就是四条硬要求：</p><ol><li><strong>具体</strong> —— 说文件名、说行数、说函数名（「在 <code>graph/supervisor.py</code> 的 <code>run_react</code> 里」），不要说「在编排层里」。</li><li><strong>有取舍</strong> —— 每个技术选择都要能说出<strong>被放弃的那个方案</strong>和放弃的理由。</li><li><strong>有排查过程</strong> —— 讲故障时讲「我怎么定位的」，不只讲「我改了什么」。</li><li><strong>不越界</strong> —— 没做过的就说没做。面试官见过太多编的数字，一旦被戳穿，前面全白讲。</li></ol><blockquote><p>你的两个项目在这四条上都有存货：源码已被逐行读过，缺陷、失败、文档与代码不一致的地方全都在事实清单里记着。<strong>这些「不完美」是你最值钱的素材</strong>——它们证明你真跑过。</p></blockquote><h2 id="口径卡-先背这两张" tabindex="-1">口径卡（先背这两张） <a class="header-anchor" href="#口径卡-先背这两张" aria-label="Permalink to &quot;口径卡（先背这两张）&quot;">​</a></h2><h3 id="yyhelp-·-电商客服多轮对话-agent" tabindex="-1">YYHelp · 电商客服多轮对话 Agent <a class="header-anchor" href="#yyhelp-·-电商客服多轮对话-agent" aria-label="Permalink to &quot;YYHelp · 电商客服多轮对话 Agent&quot;">​</a></h3><p><strong>一句话</strong>：用 LangGraph 状态图把 9 类意图分流到 5 个出口，各子流程汇合到主力 Agent 的 ReAct 循环——解决的不是「检索准不准」，是<strong>多轮对话能不能可靠地把事办完</strong>。</p><p><strong>三个必须带口径的数字</strong>：</p><table tabindex="0"><thead><tr><th>说法</th><th>口径（必须一起说）</th></tr></thead><tbody><tr><td>多智能体 vs 单智能体：<strong>完成率 −14.2pp + 墙钟 1.43×，双 REGRESSION</strong></td><td><strong>120 题</strong>×2 臂配对；完成率 <strong>63.3% vs 77.5%</strong>（p=0.00053）、墙钟 <strong>24.7s vs 17.3s</strong>（p≈0）显著更差；只有 tokens <strong>省 12.5%</strong>（IMPROVEMENT）。结论：<strong>不切换多智能体</strong>。⚠️ 首轮 40 题的数字（100%/97.5%、2.11×）<strong>已被证伪</strong>，四轮链条见 <a href="/learn/interview/architecture-ab.html">⭐ 架构对比实验</a></td></tr><tr><td><strong>11 个 selftest 从未被执行</strong></td><td>这是 v1 的 grep 结果；说明「代码写下了」和「CI 真的跑了」是两件事</td></tr><tr><td>文档与代码不一致 <strong>9 处</strong></td><td>例：README 写「9 个新字段」实为 <strong>14</strong>；<code>longterm.py</code> docstring 写 7 组 selftest 实为 <strong>10 组</strong></td></tr></tbody></table><p><strong>三个能撑住追问链的缺陷</strong>：<code>run_react</code> 缺 <code>state</code> 形参 → 异常被吞成 <code>model_error</code>；<code>getattr(llm, &quot;model&quot;)</code> 同一个错<strong>逐字复发在两处</strong>；bottleneck 块构造持有 GIL，把并行收益从 <strong>1.02× 掩盖到 6.41×</strong>。</p><h3 id="科研文献-rag-问答" tabindex="-1">科研文献 RAG 问答 <a class="header-anchor" href="#科研文献-rag-问答" aria-label="Permalink to &quot;科研文献 RAG 问答&quot;">​</a></h3><p><strong>一句话</strong>：面向 AI 领域科研文献的「混合检索 + 重排序 + 引用溯源 + 拒答」问答服务，外加一套分层评测集。</p><p><strong>三个必须带口径的数字</strong>：</p><table tabindex="0"><thead><tr><th>说法</th><th>口径（必须一起说）</th></tr></thead><tbody><tr><td>双层拒答，两层误拒率 <strong>1.6% vs 6.5%</strong></td><td>程序层 = rerank top1 <code>&lt; 0.30</code> 零成本拒答；模型层 = 自报 <code>insufficient</code> 兜底。可回答题 top1 中位 <strong>0.9617</strong> vs 不可回答 <strong>0.0127</strong></td></tr><tr><td><strong><code>Recall@10 == Recall@5</code> 不是排序完美</strong></td><td>那是我自己标注窗口造成的构造结果——机器 gt 的候选只取了前 5 个。修正后立刻暴露「不做精排时 R@10 比 R@5 高 <strong>11–14pp</strong>」</td></tr><tr><td>首字延迟 <strong>14.9 s</strong>，瓶颈不是 LLM</td><td>实测 14.90 / 10.00 / 14.86 s；其中 <strong>CPU 精排 20 对约 8.5 s</strong>，LLM 生成 P50 只有 <strong>1.26 s</strong>。优化方向一开始搞错了</td></tr></tbody></table><p><strong>两个能撑住追问链的发现</strong>：<code>SPARSE_MODE=overlap</code> 的<strong>自检失效</strong>机制（扩库后混合检索 R@5 从 <strong>64.5% 崩到 29.2%</strong>，根因是中文查询的 BM25 top-20 全来自那两篇中文文献——<strong>「同语言 ≠ 同主题」</strong>）；预热做了但没生效（<code>/health</code> 秒回 200 ⇒ 编排在模型加载前就把流量导进来，第一个请求照样等 <strong>48 秒</strong>）。</p><h2 id="三条纪律" tabindex="-1">三条纪律 <a class="header-anchor" href="#三条纪律" aria-label="Permalink to &quot;三条纪律&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">报数必带口径</p><p>「recall@5 是 64.5%」这句话本身没有信息量。必须说：macro 还是 micro、k 是多少、有没有过精排、分母怎么定义、ground truth 谁标的。<strong>面试官只要追问一句「这个数怎么算的」，口径不全的人就露馅了。</strong></p></div><div class="warning custom-block"><p class="custom-block-title">不假装跑过</p><p>没测的就写「未验证」，并给出你会怎么验证。你两个项目的事实清单里都专门有一节叫「未实测 / 未验证清单」——<strong>带着这个去面试，比编三个漂亮数字安全一百倍。</strong></p></div><div class="warning custom-block"><p class="custom-block-title">配置类开关必须配「能失败的断言」</p><p>只验「没报错」等于没验。中文 BM25 静默返回空就是活例子：不报错、不抛异常、只给你一个空列表。<strong>任何一个开关，你都要能说出「我怎么知道它真的生效了」。</strong></p></div><h2 id="这一节八页怎么分工" tabindex="-1">这一节八页怎么分工 <a class="header-anchor" href="#这一节八页怎么分工" aria-label="Permalink to &quot;这一节八页怎么分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>覆盖什么</th><th>什么时候读</th></tr></thead><tbody><tr><td><a href="/learn/interview/cheatsheet.html">🔥 面试随身数字卡</a></td><td>两个项目所有可引用数字 + 口径 + 出处 + <strong>「不能报的数」黑名单</strong></td><td><strong>面试前 5 分钟</strong></td></tr><tr><td><a href="/learn/interview/project-grilling.html">项目深挖预演</a></td><td>两个项目的三层追问链、口径卡、被戳穿时的救场话术</td><td><strong>最先读</strong></td></tr><tr><td><a href="/learn/interview/rag.html">RAG 高频题</a></td><td>切块、混合检索、RRF、精排、拒答、评测、GraphRAG</td><td>面 RAG 岗前</td></tr><tr><td><a href="/learn/interview/agent.html">Agent 与工具调用高频题</a></td><td>ReAct、Function Calling、MCP、多智能体、记忆、终止条件</td><td>面 Agent 岗前</td></tr><tr><td><a href="/learn/interview/llm.html">大模型原理高频题</a></td><td>注意力、位置编码、KV Cache、训练三阶段、LoRA、推理优化</td><td>面大模型岗前</td></tr><tr><td><a href="/learn/interview/engineering.html">工程与系统设计题</a></td><td>限流、幂等、降级、可观测、灰度、liveness/readiness</td><td>通用后端轮</td></tr><tr><td><a href="/learn/interview/coding.html">手撕与算法</a></td><td>高频手写题 + 提示工程题</td><td>每轮技术面前</td></tr><tr><td><a href="/learn/projects/yyhelp/">项目地图 · YYHelp</a> / <a href="/learn/projects/rag/">RAG</a></td><td>项目本身的完整拆解</td><td>有整块时间时</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>学习节奏与投递窗口倒排：<a href="/learn/roadmap/">学习路线</a></li><li>自评分数与错题本：<a href="/learn/roadmap/progress.html">进度看板</a></li><li>要默画出来的图：<a href="/learn/diagrams/">架构图库</a></li><li>知识体系分层（面试权重最高的是 L3 RAG 与 L4 Agent）：<a href="/learn/kb/">知识体系总览</a></li></ul>`,31)])])}const b=r(s,[["render",o]]);export{c as __pageData,b as default};
